# Example of validating a URL and user ID
import re

def is_valid_url(url: str) -> bool:
    pattern = re.compile(r'^(https?://[^\s/$.?#].[^\s]*)$')
    return bool(pattern.match(url))

def is_valid_user_id(user_id: str) -> bool:
    return bool(user_id) and isinstance(user_id, str)

# Test the validation functions
print(is_valid_url('https://example.com/api/user'))  # Should return True
print(is_valid_user_id('aBc123'))                     # Should return True
print(is_valid_user_id(''))                            # Should return False
